def _needs_upgrade():
    version_configured = options.get("sentry:version-configured")
    if not version_configured:
        # If we were never previously upgraded (being a new install)
        # we want to force an upgrade, even if the values are set.
        return True

    smtp_disabled = not is_smtp_enabled()

    # Check all required options to see if they've been set
    for key in options.filter(flag=options.FLAG_REQUIRED):
        # ignore required flags which can be empty
        if key.flags & options.FLAG_ALLOW_EMPTY:
            continue
        # Ignore mail.* keys if smtp is disabled
        if smtp_disabled and key.name[:5] == "mail.":
            continue
        if not options.isset(key.name):
            return True

    if version_configured != sentry.get_version():
        # Everything looks good, but version changed, so let's bump it
        options.set("sentry:version-configured", sentry.get_version())

    return False

def _get_statuspage():
    id = settings.STATUS_PAGE_ID
    if id is None:
        return None
    return {"id": id, "api_host": settings.STATUS_PAGE_API_HOST}

def _get_public_dsn():

    if settings.SENTRY_FRONTEND_DSN:
        return settings.SENTRY_FRONTEND_DSN

    if settings.IS_DEV and not settings.SENTRY_USE_RELAY:
        return ""

    project_id = settings.SENTRY_FRONTEND_PROJECT or settings.SENTRY_PROJECT
    if project_id is None:
        return None

    cache_key = f"dsn:{project_id}"

    result = cache.get(cache_key)
    if result is None:
        key = project_key_service.get_project_key(project_id, ProjectKeyRole.store)
        if key:
            result = key.dsn_public
        else:
            result = ""
        cache.set(cache_key, result, 60)
    return result

def _delete_activeorg(session):
    if session and "activeorg" in session:
        del session["activeorg"]

def _resolve_last_org(session, user):
    last_org_slug = session["activeorg"] if session and "activeorg" in session else None
    if not last_org_slug:
        return None
    try:
        last_org = Organization.objects.get_from_cache(slug=last_org_slug)
        if user is not None and not isinstance(user, AnonymousUser):
            try:
                get_cached_organization_member(user.id, last_org.id)
                return last_org
            except OrganizationMember.DoesNotExist:
                return None
    except Organization.DoesNotExist:
        pass
    return None

def generate_organization_url(org_slug: str) -> str:
    org_url_template: str = options.get("system.organization-url-template")
    if not org_url_template:
        return options.get("system.url-prefix")  # type: ignore[no-any-return]
    return org_url_template.replace("{hostname}", generate_organization_hostname(org_slug))

def generate_region_url() -> str:
    region_url_template: str = options.get("system.region-api-url-template")
    region = options.get("system.region") or None
    if not region_url_template or not region:
        return options.get("system.url-prefix")  # type: ignore[no-any-return]
    return region_url_template.replace("{region}", region)

def is_active_superuser(request):
    if is_system_auth(getattr(request, "auth", None)):
        return True
    su = getattr(request, "superuser", None) or Superuser(request)
    return su.is_active

def has_user_registration():
    from sentry import features, options

    return features.has("auth:register") and options.get("auth.allow-registration")

def is_self_hosted():
    # Backcompat for rename to support old consumers, particularly single-tenant.
    from django.conf import settings

    try:
        return settings.SENTRY_SELF_HOSTED
    except AttributeError:
        return settings.SENTRY_ONPREMISE
